    "行政手続法の法令に地方公共団体の執行機関の規則も含まれる",
    "名宛人の同意の下にされる処分は、行政手続法の不利益処分から適用除外される",
    "行政手続法の行政指導は、特定の者を対象とする",
    "行政指導に携わる者は、相手方に対し趣旨、内容、責任者の明示は、すべての行政指導に適用",
    "行政指導指針は行政上特別の支障がない限り、定め、公表しなければならない",
    "免許取り消し処分は、行政手続法上の不利益処分にあたる",
