    "審査基準を公にすることにより、行政上特別の支障を生じるの場合、公にしなくとも違法とはならない",
    "処分基準を定めること、公にすることは努力義務",
    "審査基準を作成、公にすることは義務である",
    "審査基準を公にする方法は、事務所による備え付け、その他適当な方法による",
    "申請がその期間外にされても、当然に不適法とはならず、速やかに補正を求めるか、拒否しなければならない",
    "申請に必要な書類が添付されていない場合、速やかに補正を求めるか、拒否しなければならない",
    "行政庁が申請拒否処分をする場合、第三者の利益を考慮する要件がある場合、公聴会を開催するよう努めなければならない",
    "行政庁が申請の取り下げや、変更を求める行政指導を行う場合、申請者がそれに従う意思がないにもかかわらず、これを継続する等により当該申請者の権利の行使を妨げるものでないかぎり、直ちに違法とはされない",
    "行政庁が申請の処理につき、標準処理期間を経過したとしても、当該申請が拒否された訳ではない。",
