    "聴聞では参加人の制度があり、弁明にはない",
    "弁明には、当事者による文書閲覧権はない",
    "申請拒否処分には、意見陳述の規定はない",
    "不利益処分には公聴会の規定はない",
    "弁明は行政庁が口頭ですることを認めたときを除き、書面でする",
    "聴聞の内容に対する不服は、行政不服審査法の審査請求の対象外",
